        mr=min(r for r,_ in cur); mc=min(c for _,c in cur)
        nrm=tuple(sorted((r-mr,c-mc) for r,c in cur))
        outs.add(nrm)
        rv=[(-r,c) for r,c in cur]; mr2=min(r for r,_ in rv); mc2=min(c for _,c in rv)
        nf=tuple(sorted((r-mr2,c-mc2) for r,c in rv))
        outs.add(nf)
        cur=[(c,-r) for r,c in cur]
    return sorted(outs)
