    for i in range(h):
        for j in range(w):
            if I[i][j]!=O[i][j]: D[O[i][j]].add((i,j))
    # for each seed color, candidate (transform,offset) whose stamp covers ALL diff cells of that color
    cand={}
    for col,S in D.items():
        good=[]
        for vi,P in enumerate(Tns):
